from pathlib import Path
import base64, gzip, hashlib, re, shutil

ROOT=Path('.')
VIEWER=ROOT/'skills/repoaxis/viewer'
EXPECTED='5cbb82c3014d32e88a64860cc55fa6213813b353a98b6b3b151c7eef745a960d'
parts=[ROOT/'.v47-r00/chunk-02.b64',ROOT/'.v47-r00/gz-01.b64',ROOT/'.v47-r00/gz-02.b64',ROOT/'.v47-r00/gz-03.b64',ROOT/'.v47-r00/gz-04.b64']
encoded=''.join(p.read_text().strip() for p in parts)
html=gzip.decompress(base64.b64decode(encoded))
actual=hashlib.sha256(html).hexdigest()
if actual!=EXPECTED: raise SystemExit(f'canonical v47 sha mismatch: {actual}')
(VIEWER/'repoaxis.html').write_bytes(html)
for p in VIEWER.iterdir():
    if p.name!='repoaxis.html' and p.is_file(): p.unlink()

server=ROOT/'skills/repoaxis/lib/view-server.mjs'
s=server.read_text()
s=re.sub(r'const VIEWER_ASSETS = new Map\(\[.*?\]\);\n','',s,flags=re.S)
s=re.sub(r'\n    if \(VIEWER_ASSETS\.has\(url\.pathname\)\) \{.*?\n    \}','',s,count=1,flags=re.S)
server.write_text(s)

snapshot=ROOT/'skills/repoaxis/lib/view-snapshot.mjs'
snapshot.write_text('''import fs from "node:fs";\nimport path from "node:path";\nimport process from "node:process";\nimport { startViewer } from "./view-server.mjs";\n\nfunction snapshotBootstrap(payload) {\n  const serialized = JSON.stringify(payload).replace(/</g, "\\\\u003c");\n  return `<script data-repoaxis-snapshot-bootstrap>\\nwindow.__REPOAXIS_SNAPSHOT__=${serialized};\\nwindow.fetch=async function(input){\\n  const raw=typeof input==='string'?input:(input&&input.url)||'';\\n  let pathname='';\\n  try{pathname=new URL(raw,'http://repoaxis.snapshot').pathname}catch{}\\n  const response=window.__REPOAXIS_SNAPSHOT__.responses[pathname];\\n  if(!response)throw new Error('Frozen Repoaxis snapshot has no resource for '+(pathname||raw));\\n  return new Response(JSON.stringify(response),{status:200,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});\\n};\\n</script>`;\n}\n\nasync function fetchText(base, pathname) {\n  const response = await fetch(new URL(pathname, base));\n  if (!response.ok) throw new Error(`${pathname} returned HTTP ${response.status}`);\n  return response.text();\n}\n\nasync function fetchJson(base, pathname) {\n  const response = await fetch(new URL(pathname, base));\n  const value = await response.json();\n  if (!response.ok || value?.ok === false) throw new Error(value?.error || `${pathname} returned HTTP ${response.status}`);\n  return value;\n}\n\nexport async function writeViewerSnapshot({ root = process.cwd(), output = null } = {}) {\n  const viewer = await startViewer({ root, port: 0, open: false });\n  try {\n    const [shell, indexResponse, metaResponse, historyResponse] = await Promise.all([\n      fetchText(viewer.url, "/"), fetchJson(viewer.url, "/api/index"), fetchJson(viewer.url, "/api/meta"), fetchJson(viewer.url, "/api/history"),\n    ]);\n    const capturedAt = new Date().toISOString();\n    const payload = { format: "repoaxis-viewer-snapshot-v1", captured_at: capturedAt, responses: {\n      "/api/index": { ...indexResponse, refreshed: false, reason: "snapshot" },\n      "/api/meta": { ...metaResponse, source_host_label: metaResponse.host_label, host_label: "Snapshot" },\n      "/api/history": historyResponse,\n    }};\n    let outputHtml = shell.replace(/<title>[^<]*<\\/title>/, "<title>Repoaxis — Frozen Snapshot</title>");\n    outputHtml = outputHtml.replace("</head>", `${snapshotBootstrap(payload)}\\n</head>`);\n    outputHtml = outputHtml.replace("<body>", `<body data-repoaxis-mode="snapshot" data-repoaxis-captured-at="${capturedAt}">`);\n    if (/\\b(?:src|href)="\\/viewer-/.test(outputHtml)) throw new Error("snapshot contains external viewer assets");\n    const outputFile = path.resolve(output ?? path.join(viewer.root, "repoaxis-snapshot.html"));\n    fs.mkdirSync(path.dirname(outputFile), { recursive: true });\n    fs.writeFileSync(outputFile, outputHtml, "utf8");\n    return { ok: true, output: outputFile, root: viewer.root, captured_at: capturedAt, repository: metaResponse.display_name, head_sha: indexResponse.index?.repository?.head_sha ?? null, bytes: Buffer.byteLength(outputHtml) };\n  } finally { await new Promise((resolve) => viewer.server.close(resolve)); }\n}\n''')

for p in (ROOT/'dev/tests/integration').glob('viewer-*.test.mjs'): p.unlink()
viewer_test=ROOT/'dev/tests/integration/viewer.test.mjs'
viewer_test.write_text('''import assert from "node:assert/strict";\nimport { execFileSync } from "node:child_process";\nimport crypto from "node:crypto";\nimport fs from "node:fs";\nimport os from "node:os";\nimport path from "node:path";\nimport { fileURLToPath } from "node:url";\nimport test from "node:test";\nimport { startViewer } from "../../../skills/repoaxis/lib/view-server.mjs";\nconst VIEWER_DIR=fileURLToPath(new URL("../../../skills/repoaxis/viewer/",import.meta.url)),VIEWER_HTML=path.join(VIEWER_DIR,"repoaxis.html"),V47_SHA="5cbb82c3014d32e88a64860cc55fa6213813b353a98b6b3b151c7eef745a960d";\nfunction git(root,...args){return execFileSync("git",["-C",root,...args],{encoding:"utf8",stdio:["ignore","pipe","pipe"]}).trim()}\nfunction createRepo(){const root=fs.mkdtempSync(path.join(os.tmpdir(),"repoaxis-viewer-"));fs.mkdirSync(path.join(root,"src"),{recursive:true});fs.writeFileSync(path.join(root,"src","util.js"),"export const value = 1;\\n");fs.writeFileSync(path.join(root,"src","main.js"),"import { value } from './util.js';\\nexport function main(){ return value; }\\n");fs.writeFileSync(path.join(root,"src","legacy.js"),"export const legacy = true;\\n");git(root,"init","-q","-b","main");git(root,"config","user.name","Repoaxis Viewer Test");git(root,"config","user.email","repoaxis@example.invalid");git(root,"remote","add","origin","git@github.com:example/repoaxis-viewer-fixture.git");git(root,"add",".");git(root,"commit","-qm","fixture");fs.writeFileSync(path.join(root,"src","util.js"),"export const value = 2;\\n");fs.rmSync(path.join(root,"src","legacy.js"));git(root,"add","-A");git(root,"commit","-qm","update util and remove legacy");return root}\ntest("viewer directory is exactly the canonical single-file v47 shell",()=>{assert.deepEqual(fs.readdirSync(VIEWER_DIR).sort(),["repoaxis.html"]);const html=fs.readFileSync(VIEWER_HTML,"utf8"),sha=crypto.createHash("sha256").update(html).digest("hex");assert.equal(sha,V47_SHA);assert.match(html,/Repository Intelligence Prototype v47/);for(const id of ["structureStage","dependenciesStage","changesStage","graphStage","drawer"])assert.match(html,new RegExp(`id="${id}"`));for(const fn of ["renderOverview","renderDependencies","renderChanges","renderGraph","navigateSelectedTo","openChangeSetGraphV18","impactPathsV21"])assert.match(html,new RegExp(`function ${fn}|${fn}=function`));assert.doesNotMatch(html,/(?:src|href)="\\/viewer-/);for(const m of html.matchAll(/<script>([\\s\\S]*?)<\\/script>/g))assert.doesNotThrow(()=>new Function(m[1]))});\ntest("viewer server serves canonical shell plus live read-only APIs only",async()=>{const root=createRepo(),viewer=await startViewer({root,port:0,open:false});try{assert.equal(viewer.host,"127.0.0.1");const page=await fetch(viewer.url);assert.equal(page.status,200);assert.match(await page.text(),/Repository Intelligence Prototype v47/);for(const asset of ["/viewer-base.css","/viewer-surfaces.css","/viewer-0.js","/viewer-5.js"])assert.equal((await fetch(new URL(asset,viewer.url))).status,404);const first=await fetch(new URL("/api/index",viewer.url)).then(r=>r.json());assert.equal(first.ok,true);assert.equal(first.index.generated.edges.some(e=>e.type==="imports"),true);const meta=await fetch(new URL("/api/meta",viewer.url)).then(r=>r.json());assert.equal(meta.display_name,"example/repoaxis-viewer-fixture");assert.equal(meta.host_label,"GitHub");const history=await fetch(new URL("/api/history",viewer.url)).then(r=>r.json());assert.equal(history.commit.subject,"update util and remove legacy");assert.equal(history.changes.some(c=>c.path==="src/legacy.js"&&c.status==="D"),true);const health=await fetch(new URL("/api/health",viewer.url)).then(r=>r.json());assert.deepEqual(health,{ok:true,repository:".",host:"127.0.0.1"});fs.writeFileSync(path.join(root,"src","util.js"),"export const value = 3;\\n");const second=await fetch(new URL("/api/index",viewer.url)).then(r=>r.json());assert.equal(second.index.generated.nodes["file:src/util.js"].git.working,"modified");for(const endpoint of ["/api/index","/api/meta","/api/history"])assert.equal((await fetch(new URL(endpoint,viewer.url),{method:"POST"})).status,405)}finally{await new Promise(resolve=>viewer.server.close(resolve))}});\n''')

snap_test=ROOT/'dev/tests/integration/viewer-snapshot.test.mjs'
snap_test.write_text('''import assert from "node:assert/strict";\nimport { execFileSync } from "node:child_process";\nimport fs from "node:fs";\nimport os from "node:os";\nimport path from "node:path";\nimport { fileURLToPath } from "node:url";\nimport test from "node:test";\nimport { writeViewerSnapshot } from "../../../skills/repoaxis/lib/view-snapshot.mjs";\nconst BIN=fileURLToPath(new URL("../../../bin/repoaxis",import.meta.url));\nfunction git(root,...args){return execFileSync("git",["-C",root,...args],{encoding:"utf8",stdio:["ignore","pipe","pipe"]}).trim()}\nfunction createRepo(){const root=fs.mkdtempSync(path.join(os.tmpdir(),"repoaxis-snapshot-"));fs.mkdirSync(path.join(root,"src"),{recursive:true});fs.writeFileSync(path.join(root,"src","util.js"),"export const value = 1;\\n");fs.writeFileSync(path.join(root,"src","main.js"),"import { value } from './util.js';\\nexport const result = value;\\n");git(root,"init","-q","-b","main");git(root,"config","user.name","Repoaxis Snapshot Test");git(root,"config","user.email","repoaxis@example.invalid");git(root,"remote","add","origin","git@github.com:example/repoaxis-snapshot-fixture.git");git(root,"add",".");git(root,"commit","-qm","snapshot fixture");fs.writeFileSync(path.join(root,"src","util.js"),"export const value = 2;\\n");return root}\nfunction embeddedPayload(html){const marker="window.__REPOAXIS_SNAPSHOT__=",start=html.indexOf(marker);assert.notEqual(start,-1);const valueStart=start+marker.length,end=html.indexOf(";\\nwindow.fetch=async function",valueStart);assert.notEqual(end,-1);return JSON.parse(html.slice(valueStart,end))}\ntest("snapshot freezes live API payload into the same single-file v47 shell",async()=>{const root=createRepo(),output=path.join(root,"artifacts","viewer.html"),result=await writeViewerSnapshot({root,output});assert.equal(result.ok,true);const html=fs.readFileSync(output,"utf8");assert.match(html,/<title>Repoaxis — Frozen Snapshot<\\/title>/);assert.match(html,/data-repoaxis-mode="snapshot"/);assert.match(html,/window\\.__REPOAXIS_SNAPSHOT__/);assert.doesNotMatch(html,/(?:src|href)="\\/viewer-/);const payload=embeddedPayload(html);assert.equal(payload.format,"repoaxis-viewer-snapshot-v1");assert.equal(payload.responses["/api/meta"].host_label,"Snapshot");assert.equal(payload.responses["/api/history"].commit.subject,"snapshot fixture");assert.equal(payload.responses["/api/index"].reason,"snapshot");assert.equal(payload.responses["/api/index"].refreshed,false)});\ntest("repoaxis snapshot remains a first-class CLI command",()=>{assert.match(execFileSync(process.execPath,[BIN,"help"],{encoding:"utf8"}),/repoaxis snapshot \\[--root PATH\\] \\[--output FILE\\]/);const root=createRepo(),output=path.join(root,"snapshot.html"),result=JSON.parse(execFileSync(process.execPath,[BIN,"snapshot","--root",root,"--output",output],{encoding:"utf8"}).trim());assert.equal(result.ok,true);assert.match(fs.readFileSync(output,"utf8"),/window\\.__REPOAXIS_SNAPSHOT__/)});\n''')

evidence=ROOT/'dev/visuals/v47-r00-canonical-viewer-reset.snapshot.md'
evidence.write_text('''# V47-R00 — Canonical viewer reset\n\nDate: 2026-09-03\n\n- UI/UX authority is the supplied `repoaxis_saas_prototype_v47(2).html` as one canonical source file.\n- Canonical SHA-256: `5cbb82c3014d32e88a64860cc55fa6213813b353a98b6b3b151c7eef745a960d`.\n- `skills/repoaxis/viewer/` contains only `repoaxis.html`; the split `viewer-*.js` / `viewer-*.css` reconstruction has been removed.\n- R00 intentionally does not wire live repository data into the prototype yet. Its fixture arrays and existing v47 interaction state machine remain byte-identical.\n- The loopback `/api/index`, `/api/meta`, `/api/history`, and `/api/health` backend contracts remain available for R01+ wiring.\n- `repoaxis snapshot` freezes those API payloads into the already self-contained canonical HTML rather than inlining a second viewer asset graph.\n- Split-viewer implementation tests were removed and replaced with single-file authority/server/snapshot boundary tests.\n\nNo index schema, Git semantics, query semantics, release workflow, or canonical repository analysis logic changed in R00.\n''')

